+// Docker's ENV takes everything after the key as the value, so a trailing `# comment`
+// becomes part of it and the setting coerces to NaN. The image's settings must parse.
+describe('Dockerfile', () => {
+  const lines = readFileSync(new URL('../Dockerfile', import.meta.url), 'utf8').split('\n');
+
+  const env = new Map<string, string>();
+  for (const line of lines) {
+    const [, key, value] = /^ENV\s+(\w+)(?:\s+|=)(.+)$/.exec(line) ?? [];
+    if (key && value) env.set(key, value);
+  }
+
+  it('sets no ENV value with an inline comment', () => {
+    for (const [key, value] of env) expect(value, key).not.toContain('#');
+  });
+
+  it('sets shop settings the app can parse', () => {
